import{_ as t,o,c as e,a2 as n}from"./chunks/framework.BXA5Pi9t.js";const d=JSON.parse('{"title":"Ceph Crimson/SeaStor OSD 2020-10-28","description":"","frontmatter":{"title":"Ceph Crimson/SeaStor OSD 2020-10-28","date":"2020-10-28T00:00:00.000Z","updated":"2020-11-03T00:00:00.000Z","tags":["Ceph","分布式存储","性能优化","代码审查","测试验证"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-10-28.md","filePath":"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-10-28.md","lastUpdated":1780460162000}'),s={name:"posts/2020/Ceph_Crimson_SeaStor_OSD_2020-10-28.md"};function a(i,r,l,g,h,p){return o(),e("div",null,[...r[0]||(r[0]=[n('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><h4 id="关键细节" tabindex="-1">关键细节 <a class="header-anchor" href="#关键细节" aria-label="Permalink to &quot;关键细节&quot;">​</a></h4><ul><li><strong>Johannes Pierre的审查</strong>：会议开始时提到，上周对Johannes Pierre的“interpretable future”进行了审查，并希望尽快完成。</li><li><strong>修复occluded by unknown问题</strong>：讨论了在服务客户端请求时，如何修复因未知原因导致的对象遮挡问题。</li><li><strong>PG acting sets的变化</strong>：在处理客户端请求时，PG的acting sets发生了变化，需要重新启动客户端请求。</li><li><strong>PR的更新</strong>：对PR进行了一些更改，目前正在解决编译错误，并计划运行thresh测试。</li><li><strong>单元测试的缺失</strong>：发现目前没有可用的单元测试来检查恢复过程，可能需要在整个trash测试中运行。</li><li><strong>时间区变更</strong>：从明天开始，将前往加拿大，时间区会有所变化，但仍会参与会议。</li><li><strong>代码清理和PR提交</strong>：计划清理代码并提交PR进行审查，同时在测试中发现了一个bug，需要修复并提供测试用例。</li><li><strong>扩展map tree的问题</strong>：在扩展map tree时遇到了问题，计划发送详细信息给团队成员帮助解决。</li><li><strong>NBD服务器实现</strong>：为了测试Ceph的不同元素，实现了一个简单的NBD服务器，将I/O操作直接传递给事务管理器。</li><li><strong>NVMe over Fabric的讨论</strong>：讨论了如何在未来的Rados中适应NVMe over Fabric，以及如何改变Rados协议以允许客户端在没有协调的情况下进行写操作。</li><li><strong>Optane内存的使用</strong>：讨论了如何利用Optane内存来提高性能，特别是在元数据和日志缓存方面。</li><li><strong>多核Crimson的实现</strong>：计划实现多核Crimson，以提高性能和覆盖更多的测试场景。</li></ul><h4 id="主要议题" tabindex="-1">主要议题 <a class="header-anchor" href="#主要议题" aria-label="Permalink to &quot;主要议题&quot;">​</a></h4><ul><li><strong>Ceph存储系统的性能和稳定性改进</strong>：包括修复已知问题、优化代码、增加测试覆盖率以及探索新的硬件加速技术。</li><li><strong>分布式存储系统的未来发展方向</strong>：讨论了如何适应新的硬件技术（如NVMe over Fabric）和内存技术（如Optane），以及如何改进协议以提高效率。</li></ul><h4 id="决定事项" tabindex="-1">决定事项 <a class="header-anchor" href="#决定事项" aria-label="Permalink to &quot;决定事项&quot;">​</a></h4><ul><li><strong>继续审查和完善PR</strong>：确保代码质量和功能完整性。</li><li><strong>增加单元测试</strong>：以确保系统的稳定性和可靠性。</li><li><strong>实现NBD服务器</strong>：用于更有效地测试Ceph的各个组件。</li><li><strong>探索NVMe over Fabric的应用</strong>：以提高存储系统的性能。</li><li><strong>利用Optane内存</strong>：特别是在元数据和日志缓存方面。</li><li><strong>实现多核Crimson</strong>：以提高系统的并行处理能力。</li></ul><h4 id="后续行动计划" tabindex="-1">后续行动计划 <a class="header-anchor" href="#后续行动计划" aria-label="Permalink to &quot;后续行动计划&quot;">​</a></h4><ul><li><strong>完成PR的审查和测试</strong>：确保所有更改都经过充分的测试。</li><li><strong>设计和实现单元测试</strong>：以覆盖所有关键功能。</li><li><strong>继续研究和开发NBD服务器</strong>：以支持更复杂的测试场景。</li><li><strong>深入研究NVMe over Fabric和Optane内存的应用</strong>：以确定最佳实践和实施方案。</li><li><strong>推进多核Crimson的实现</strong>：以提高系统的性能和可靠性。</li></ul><p>本次会议涵盖了Ceph存储系统的多个关键技术和未来发展方向，旨在通过技术改进和创新，提高系统的性能、稳定性和可扩展性。</p>',10)])])}const c=t(s,[["render",a]]);export{d as __pageData,c as default};
